 "content": "from collections import Counter, deque


def transform(grid):
    """Replace isolated color-noise pixels with the locally supported color."""
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = g[r][c]
            q = [(r, c)]
            seen[r][c] = True
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and g[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append((color, comp))

    # The coherent regions are the underlying picture; singleton components
    # are stray pixels laid over those regions.
    noisy = {cell for _, comp in components if len(comp) == 1 for cell in comp}
    stable = [[g[r][c] for c in range(w)] for r in range(h)]
    for r, c in noisy:
        stable[r][c] = None

    out = [row[:] for row in stable]
    for r, c in noisy:
        votes = Counter()
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if dy == 0 and dx == 0:
                    continue
                y, x = r + dy, c + dx
                if 0 <= y < h and 0 <= x < w and stable[y][x] is not None:
                    votes[stable[y][x]] += 2 if dy == 0 or dx == 0 else 1
        if votes:
            best = max(votes.values())
            tied = [color for color, count in votes.items() if count == best]
            if len(tied) > 1:
                # Break ties by the closest supporting cells, then by their count.
                distances = {color: 99 for color in tied}
                for color in tied:
                    for y in range(h):
                        for x in range(w):
                            if stable[y][x] == color:
                                distances[color] = min(distances[color], abs(y-r) + abs(x-c))
                tied.sort(key=lambda color: (distances[color], -votes[color], color))
            out[r][c] = tied[0]
        else:
            # Rare fallback: nearest coherent cell in the grid.
            candidates = [(abs(y-r) + abs(x-c), stable[y][x])
                          for y in range(h) for x in range(w) if stable[y][x] is not None]
            out[r][c] = min(candidates)[1]
    return out
