    stable = [row[:] for row in g]
    for r, c in noisy:
        stable[r][c] = None
    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    out = [row[:] for row in g]

    for r, c in noisy:
        # A speck inside a solid rectangular patch is an occlusion. Find the
        # largest 2-D rectangle through this pixel supported by one color.
        patch_candidates = []
        for color in range(10):
            if color == background:
                continue
            best_area = 0
            for r0 in range(r + 1):
                for r1 in range(r, h):
                    if r1 == r0:
                        continue
                    for c0 in range(c + 1):
                        for c1 in range(c, w):
                            if c1 == c0:
                                continue
                            area = (r1 - r0 + 1) * (c1 - c0 + 1)
                            if area <= best_area:
                                continue
                            ok = True
                            support = 0
                            for y in range(r0, r1 + 1):
                                for x in range(c0, c1 + 1):
                                    value = stable[y][x]
                                    if (y, x) != (r, c) and value is not None:
                                        if value != color:
                                            ok = False
                                            break
                                        support += 1
                                if not ok:
                                    break
                            if ok and support >= 3:
                                best_area = area
            if best_area:
                patch_candidates.append((best_area, color))
