    # Integral images let us recognize a solid rectangular region with one
    # isolated overpainted cell missing from its interior or edge.
    pref = [[[0] * (w + 1) for _ in range(h + 1)] for _ in range(10)]
    for color in range(10):
        p = pref[color]
        for r in range(h):
            run = 0
            for c in range(w):
                run += stable[r][c] == color
                p[r + 1][c + 1] = p[r][c + 1] + run

    def rect_count(color, r0, c0, r1, c1):
        p = pref[color]
        return p[r1 + 1][c1 + 1] - p[r0][c1 + 1] - p[r1 + 1][c0] + p[r0][c0]

    out = [row[:] for row in g]
    for r, c in noisy:
        best_area = 0
        best_colors = []
        nearby = {stable[y][x]
                  for y in range(max(0, r - 1), min(h, r + 2))
                  for x in range(max(0, c - 1), min(w, c + 2))
                  if stable[y][x] is not None and stable[y][x] != background}
        for color in nearby:
            for r0 in range(r + 1):
